import Mime from './dist/src/Mime.js';
const instance = new Mime();

const tests = [
  // LINE FEED (U+000A) without directory - should strip nothing but still find .png through the dot regex
  { input: 'LINE\nFEED.png', expected: 'image/png' },
  // Carriage return (U+000D) without directory
  { input: 'LINE\rFEED.png', expected: 'image/png' },
  // Line separator (U+2028) without directory
  { input: 'LINE\u2028FEED.png', expected: 'image/png' },
  // Paragraph separator (U+2029) without directory
  { input: 'LINE\u2029FEED.png', expected: 'image/png' },

  // With a directory part before the line terminator
  { input: 'dir/NAME\nFILE.png', expected: 'image/png' },
  { input: 'dir\\NAME\rFILE.png', expected: 'image/png' },
  { input: 'dir/NAME\u2028FILE.png', expected: 'image/png' },
  { input: 'dir\\NAME\u2029FILE.png', expected: 'image/png' },

  // Line terminator at the very beginning (no directory part, just starts with line terminator)
  { input: '\nNAME.png', expected: 'image/png' },
  { input: '\rNAME.png', expected: 'image/png' },
  { input: '\u2028NAME.png', expected: 'image/png' },
  { input: '\u2029NAME.png', expected: 'image/png' },

  // Line terminator at position where extension would be parsed
  { input: 'file\n.png', expected: 'image/png' },
];

export default function (input) {
  return instance.getType(input);
}

import Mime from './dist/src/Mime.js';
const instance = new Mime();

const tests = [
  // Normal file paths (must keep working)
  { input: 'text.txt', expected: 'text/plain' },
  { input: 'TEXT.TXT', expected: 'text/plain' },
  { input: 'txt', expected: 'text/plain' },
  { input: '.txt', expected: 'text/plain' },
  { input: 'dir/text.txt', expected: 'text/plain' },
  { input: 'dir\\text.txt', expected: 'text/plain' },
  { input: '/path/to/page.html', expected: 'text/html' },
  { input: 'c:\\path\\to\\page.html', expected: 'text/html' },
  { input: '.config.json', expected: 'application/json' },

  // Space and tab already work (from the task)
  { input: 'file name.txt', expected: 'text/plain' },
  { input: 'file\tname.txt', expected: 'text/plain' },

  // Edge cases that should return null
  { input: '.bogus', expected: null },
  { input: 'bogus', expected: null },
  { input: '/txt', expected: null },
  { input: '\\txt', expected: null },
  { input: 'text.nope', expected: null },

  // Non-string inputs must return null (unchanged behavior)
];

export default function (input) {
  return instance.getType(input);
}

